void attenuate(in float compare, in vec4 attenuation, inout vec3 color){
   color.rgb *= smoothstep(attenuation.x, attenuation.y, compare) * smoothstep(attenuation.w, attenuation.z, compare);
}
void attenuate(in float compare, in vec2 attenuation, inout vec3 color){
   color.rgb *= smoothstep(attenuation.x, attenuation.y, compare);
}
void attenuate(in float compare, in vec4 attenuation, inout vec4 color){
   color *= smoothstep(attenuation.x, attenuation.y, compare) * smoothstep(attenuation.w, attenuation.z, compare);
}
void attenuate(in float compare, in vec2 attenuation, inout vec4 color){
   color *= smoothstep(attenuation.x, attenuation.y, compare);
}
vec4 fbm(in sampler2D tex, in vec2 uv){
    vec2 _uv = uv;
    mat2 rotm = mat2(1.6, 1.2, -1.2, 1.6);
    vec4 f = 0.5000 * texture2D(tex, _uv); _uv = rotm * _uv;
    f += 0.2500 * texture2D(tex, _uv); _uv = rotm * _uv;
    f += 0.1250 * texture2D(tex, _uv); _uv = rotm * _uv;
    f += 0.0625 * texture2D(tex, _uv);
	return f;
}
