varying vec3 v_position;
varying vec3 v_normal;
uniform sampler2D mainTexture;
   uniform vec4 startColor;
   uniform vec4 fadeColor;
   uniform vec4 attenuation;
   uniform vec4 args;
vec4 frag () {
  vec2 uv = v_uv * vec2(2.0, 2.0);
  #if USE_FLOW
      uv += args.xy * cc_time.x * 0.01;
  #endif
  vec4 f = fbm(mainTexture, uv);
  vec4 color = mix(startColor * startColor.a, fadeColor * fadeColor.a, 1.-v_uv.y) * f;
  attenuate(1.-v_uv.y, attenuation, color);
  float sharpness = 2.0;
  vec3 N = normalize(v_normal);
  vec3 V = normalize(v_position - cc_cameraPos.xyz);
  float dVN = dot(N, V);
  float VN = max(abs(dVN), abs(-dVN));
  float powVN = pow(VN, sharpness);
  vec3 coma = vec3(0.);
  #if CENTRAL_REVESED
      color.rgb = mix(color.rgb, coma,  powVN);
  #else
      color.rgb = mix(coma, color.rgb,  powVN);
  #endif
  return color;
}
