      #if CC_SURFACES_LIGHTING_TT
        CCSurfacesLightingCalculateDirectTT(lightingResult, lightingData, cc_mainLitColor);
      #endif
      #if CC_SURFACES_LIGHTING_USE_MULTIPLE_LAYER_BLEND
