{
  In.position = vec4(a_position, 1.0);
  In.normal = a_normal;
#if CC_SURFACES_USE_TANGENT_SPACE
  In.tangent = a_tangent;
#endif
#if CC_SURFACES_USE_VERTEX_COLOR
  In.color = a_color;
#endif
  In.texCoord = a_texCoord;
