  VSOutput_faceSideSign = In.worldNormal.w;
  VSOutput_worldPos = In.worldPos;
#if CC_SURFACES_USE_TANGENT_SPACE
  VSOutput_worldTangent = In.worldTangent.xyz;
  VSOutput_mirrorNormal = In.tangent.w > 0.0 ? 1.0 : -1.0;
