}
#if CC_SURFACES_LIGHTING_USE_MULTIPLE_LAYER_BLEND
  void CCSurfaceLightingCalculateDirectSubLayerFresnel(out vec3 subLayerF, in LightingIntermediateData lightingData, vec3 specularColor)
  {
