  highp   mat4 cc_matViewProjInv;
  highp   vec4 cc_cameraPos;
  mediump vec4 cc_surfaceTransform;
  mediump vec4 cc_screenScale;
  mediump vec4 cc_exposure;
  mediump vec4 cc_mainLitDir;
  mediump vec4 cc_mainLitColor;
  mediump vec4 cc_ambientSky;
  mediump vec4 cc_ambientGround;
  mediump vec4 cc_fogColor;
  mediump vec4 cc_fogBase;
  mediump vec4 cc_fogAdd;
  mediump vec4 cc_nearFar;
  mediump vec4 cc_viewPort;
};
in vec3 v_position;
in vec3 v_normal;
#if USE_INSTANCING
  in vec4 instancedColor;
#endif
layout(std140) uniform Constant {
  vec4 bgColor;
  vec4 atmColor;
  vec4 solarParams;
};
vec4 frag () {
  vec3 N = normalize(v_normal);
  vec3 V = normalize(v_position - cc_cameraPos.xyz);
  float VN = max(dot(N, V), 0.0);
  vec3 lit = atmColor.rgb * atmColor.a;
  vec4 col = bgColor;
  vec3 L = cc_mainLitDir.xyz;
  #if USE_INSTANCING
      lit.rgb *= instancedColor.rgb * instancedColor.a;
  #endif
  #if USE_SOLAR_LIGHT
      L = v_position - solarParams.xyz;
  #endif
  float face = smoothstep(-.8, 0.5, dot(v_normal, -normalize(L)));
  col.rgb = mix(col.rgb, lit,  pow(VN, 2.0)) * face;
  #if USE_SOLAR_LIGHT
