vec3 drawGrids(vec2 uv, vec4 color){
    vec3 grids = color.rgb;
    const float N = 256.;
    vec2 w = fwidth(uv) + 0.01;
    vec2 a = uv + 0.5 * w;
    vec2 b = uv - 0.5 * w;
    vec2 i = (floor(a) + min(fract(a)*N, 1.0)- floor(b) - min(fract(b) * N, 1.0)) / (N * w);
    float anti = (i.x + i.y - i.x * i.y);
    grids *= anti * color.a;
