   uniform vec4 args1;
vec4 frag () {
  vec2 s_uv = v_uv + vec2(cc_time.x * args.z, 0.);
  vec4 col = mainColor;
  s_uv.x += (texture2D(noiseTexture, v_uv).r - 0.5) * 0.1 * args.w;
  float add = 1.0;
  #if USE_FLOAT
      float dis = abs(fract(args1.w * cc_time.x * args1.x) - s_uv.y);
      add *= mix(1.0, 10.0 * args1.z, smoothstep(.1 * args1.y, 0., dis));
  #endif
  #if USE_OPEN
      col.rgb += drawGrids(s_uv * vec2(args.y, 1.), lineColor) * args.x * 10.0 * add;
      col.rgb *= smoothstep(1., .8, s_uv.y);
  #else
      float lat = abs(.5-s_uv.y) * 2.0;
      col.rgb *= smoothstep(.7,.0,lat);
      col.rgb += drawGrids(s_uv * vec2(args.y, 1.), lineColor) * args.x * 10.0 * mix(0.5, 3.,lat) * add;
  #endif
  return col;
}
void main() { gl_FragColor = frag(); }

