vec2 hash(vec2 p )
{
	p = vec2( dot(p,vec2(127.1,311.7)), dot(p,vec2(269.5,183.3)) );
	return -1.0 + 2.0*fract(sin(p)*43758.5453123);
}
float noise( in vec2 p )
{
    const float K1 = 0.366025404;
    const float K2 = 0.211324865;
	vec2  i = floor( p + (p.x+p.y)*K1 );
    vec2  a = p - i + (i.x+i.y)*K2;
    float m = step(a.y,a.x);
    vec2  o = vec2(m,1.0-m);
    vec2  b = a - o + K2;
	vec2  c = a - 1.0 + 2.0*K2;
    vec3  h = max( 0.5-vec3(dot(a,a), dot(b,b), dot(c,c) ), 0.0 );
	vec3  n = h*h*h*h*vec3( dot(a,hash(i+0.0)), dot(b,hash(i+o)), dot(c,hash(i+1.0)));
    return dot( n, vec3(70.0) );
}
varying vec2 v_uv;
varying vec3 v_position;
varying vec3 v_normal;
   uniform vec4 baseColor;
   uniform vec4 comaColor;
   uniform vec4 spots;
   uniform vec4 solarParams;
   uniform float sharpness;
   uniform float spotStrength;
   uniform float nearStrength;
vec4 frag () {
  vec4 color = baseColor;
  vec3 coma = comaColor.rgb * comaColor.a;
  #if USE_RIM_LIKE
      vec3 N = normalize(v_normal);
      vec3 V = normalize(v_position - cc_cameraPos.xyz);
      float dVN = dot(N, V);
      float VN = max(abs(dVN), abs(-dVN));
      float powVN = pow(VN, sharpness);
      #if CENTRAL_REVESED
          color.rgb = mix(color.rgb, coma,  powVN);
      #else
          color.rgb = mix(coma, color.rgb,  powVN);
      #endif
  #else
      color.rgb = coma;
  #endif
  #if USE_SOLAR_LIGHT
      vec3 direction = normalize(solarParams.xyz - v_position);
      float face = smoothstep(-0.5, .5, dot(v_normal, direction));
      color.rgb *= mix(1., face, 1.0 - solarParams.w);
  #endif
  #if USE_SPOTS_NOISE
      vec2 spotScale = spots.xy;
      vec2 spotSpeed = spots.zw;
      color.rgb *= mix(noise(spotScale * (v_uv + spotSpeed * cc_time.x)), 1.0, (1.0 - spotStrength));
  #endif
  #if USE_NEAR_ATTENUATE
      float dist = length(v_position - cc_cameraPos.xyz);
      float strength = smoothstep(0.2, 0.8, dist);
      color.rgb *= nearStrength * smoothstep(0.2, 0.8, dist);;
  #endif
  return color;
}
void main() { gl_FragColor = frag(); }

