float hollowEquator(in vec2 st){
   return smoothstep(0.004, 0.005, approx(st.x, 8.0));
}
float hollowGrids(vec2 st){
   float mid = abs(st.y - .5) * .5;
   float row = smoothstep(0.003, 0.004, max(approx(st.x, gridDivision.x), mid));
   float side = 0.8 - 1.5 * abs(st.y - .5);
   float col_hor = approx(st.x, 4.0) * side;
   float col_ver = approx(st.y, gridDivision.y) * .5;
   float col = smoothstep(0.002, 0.003, max(col_hor, col_ver));
   return min(row,col);
}
vec4 frag () {
  vec4 color = mainColor;
  vec3 gc = drawGrids(v_uv * gridDivision.xy, gridColor) * 1.8;
  gc += drawGrids(v_uv * gridDivision.xy * gridDivision.zw, gridColor) * 1.5;
  vec3 ec = equatorColor.rgb * smoothstep(0.001, 0., abs(v_uv.y-0.5)) * equatorColor.a * 2.0;
  #if HOLLOW
      color.rgb += gc * hollowGrids(v_uv) + ec * hollowEquator(v_uv);
  #else
      color.rgb += gc + ec;
  #endif
  return color;
}
