#define TAN1_3 1.732
vec4 dupTexture(in vec2 uv, in sampler2D tex0, in sampler2D tex1) {
    vec4 res0 = texture(tex0, vec2(uv.x * 2.0, uv.y));
    vec4 res1 = texture(tex1, vec2(uv.x * 2.0 - 1.0, uv.y));
    return mix(res0, res1, step(0.5, uv.x));
}
float gain(float x, float k){
    float a = 0.5*pow(2.0*((x<0.5)?x:1.0-x), k);
    return (x<0.5)?a:1.0-a;
}
vec3 gain(vec3 x, float k){
    return vec3(gain(x.r,k), gain(x.g,k), gain(x.b,k));
}
vec4 gain(vec4 x, float k){
    return vec4(gain(x.r,k), gain(x.g,k), gain(x.b,k), gain(x.a,k));
}
float uvRGBNoise(in vec2 uv, in sampler2D noiseMap, in float scale, in float speed){
    vec2 st = uv / scale;
    float time = cc_time.x * speed;
    float r = texture(noiseMap, st * 1.7 + time * vec2(1., TAN1_3)).r;
    float g = texture(noiseMap, st * 2.3 + time * vec2(-1., TAN1_3)).g;
    float b = texture(noiseMap, st * 3.5 + time * vec2(0., -2.)).b;
    return gain((r+g+b), 4.0);
}
