vec4 dupTexture(in vec2 uv, in sampler2D tex0, in sampler2D tex1) {
    vec4 res0 = texture2D(tex0, vec2(uv.x * 2.0, uv.y));
    vec4 res1 = texture2D(tex1, vec2(uv.x * 2.0 - 1.0, uv.y));
