float gain(float x, float k){
    float a = 0.5*pow(2.0*((x<0.5)?x:1.0-x), k);
    return (x<0.5)?a:1.0-a;
}
vec3 gain(vec3 x, float k){
    return vec3(gain(x.r,k), gain(x.g,k), gain(x.b,k));
}
vec4 gain(vec4 x, float k){
