float uvRGBNoise(in vec2 uv, in sampler2D noiseMap, in float scale, in float speed){
    vec2 st = uv / scale;
    float time = cc_time.x * speed;
    float r = texture2D(noiseMap, st * 1.7 + time * vec2(1., TAN1_3)).r;
    float g = texture2D(noiseMap, st * 2.3 + time * vec2(-1., TAN1_3)).g;
    float b = texture2D(noiseMap, st * 3.5 + time * vec2(0., -2.)).b;
    return gain((r+g+b), 4.0);
