void SurfacesLightingModifyFinalResult(inout LightingResult result, in LightingIntermediateData lightingData, in SurfacesMaterialData surfaceData, in LightingMiscData miscData)
{
  #if USE_ATMOSPHERE_SCATTER
      vec3 P = FSInput_worldPos;
      vec3 N = FSInput_worldNormal;
      vec3 L = lightingData.L;
      vec3 V = P - cc_cameraPos.xyz;
      float NL = clamp(dot(N, L), 0.0, 1.0);
      float VL = clamp(dot(V, L), 0.0, 1.0);
      float fresnel = pow(dot(N, normalize(V)) + 1.0, 6.0);
      float backStrength = 2.0;
      float frontStrength = 5.0;
      float back = VL * smoothstep(-0.7, 1.3, dot(N, L) + 0.3) * backStrength;
      float front = (1.0 - VL) * NL * frontStrength;
      float fresnelStrength = fresnel * (back + front);
