#define TAN1_3 1.732
vec4 dupTexture(in vec2 uv, in sampler2D tex0, in sampler2D tex1) {
    vec4 res0 = texture(tex0, vec2(uv.x * 2.0, uv.y));
    vec4 res1 = texture(tex1, vec2(uv.x * 2.0 - 1.0, uv.y));
    return mix(res0, res1, step(0.5, uv.x));
}
float uvGreyNoise(in vec2 uv, in sampler2D noiseMap, in float scale, in float speed){
    vec2 st = uv / scale;
    float time = cc_time.x * speed;
    float a = texture(noiseMap, st * 2.1 + time * vec2(1., TAN1_3)).x;
    float b = texture(noiseMap, st * 3.2 + time * vec2(TAN1_3, -1.)).x;
    return (a + b) /2.;
}
