float uvGreyNoise(in vec2 uv, in sampler2D noiseMap, in float scale, in float speed){
    vec2 st = uv / scale;
    float time = cc_time.x * speed;
    float a = texture2D(noiseMap, st * 2.1 + time * vec2(1., TAN1_3)).x;
    float b = texture2D(noiseMap, st * 3.2 + time * vec2(TAN1_3, -1.)).x;
    return (a + b) /2.;
}
